type valueParser struct {
	s string
	i int
}

func parseValue(s string) (any, error) {
	p := &valueParser{s: s}
	v, e := p.value()
	if e == nil && strings.TrimSpace(p.s[p.i:]) != "" {
		e = fmt.Errorf("trailing characters")
