		return nil, fmt.Errorf("missing value")
	}
	if p.s[p.i] == '"' || p.s[p.i] == '\'' {
		return p.string()
	}
	if p.s[p.i] == '[' {
		return p.array()
	}
	if p.s[p.i] == '{' {
		return p.inline()
	}
	start := p.i
	for p.i < len(p.s) && !strings.ContainsRune(" ,\t\r\n]}", rune(p.s[p.i])) {
