			continue
		}
		i++
		if i >= len(raw) {
			return "", fmt.Errorf("invalid escape")
		}
		if raw[i] == '\n' {
			for i+1 < len(raw) && (raw[i+1] == ' ' || raw[i+1] == '\t') {
				i++
			}
			continue
		}
		switch raw[i] {
		case 'b':
			b.WriteByte('\b')
		case 't':
			b.WriteByte('\t')
		case 'n':
			b.WriteByte('\n')
		case 'f':
			b.WriteByte('\f')
		case 'r':
			b.WriteByte('\r')
		case '"', '\\':
			b.WriteByte(raw[i])
		case 'u', 'U':
