			x, e := strconv.ParseUint(raw[i+1:i+1+n], 16, 32)
			if e != nil || x > utf8.MaxRune || (x >= 0xd800 && x <= 0xdfff) {
				return "", fmt.Errorf("invalid unicode escape")
			}
